DOCUMENT();
############################################################ # Load Macros ############################################################ loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "PGessaymacros.pl", "contextForm.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
############################################################ # Header ############################################################ TEXT(beginproblem());
############################################################ # PG Setup Code ############################################################ Context()->variables->add(y=>'Real'); ($triga,$trigb) = random_subset(2,'sin','cos'); if($envir{problemSeed}==1){$triga='sin';$trigb='cos';}; #$triga='sin';$trigb='cos'; $left = Formula("($triga(x)+y)/($trigb(y)+x)"); $right = Formula("1"); if ($triga eq 'sin') { $dydx = Formula("(1-cos(x))/(sin(y)+1)")->reduce; $dydx->{test_points}=[[-3.1,-3.83041],[-0.41,0.732269],[0.59,0.759097],[2.6,1.82908],[5.3,6.93017]]; } else { $dydx = Formula("(sin(x)+1)/(1-cos(y))")->reduce; $dydx->{test_points}=[[0.831958,1],[1.329583,2],[-0.0952339,-2],[-3.70455,-3],[0.7390851,0]]; } $showwork = '[@ explanation_box(message => "Show your work using implicit differentiation.") @]*';
############################################################ # Body ############################################################
BEGIN_PGML Find [`\lz{y}{x}`] using implicit differentiation.
[`[$left]=[$right]`]
[_]{$dydx}{80}
[$showwork]**
END_PGML
############################################################ # Solution ############################################################
BEGIN_PGML_SOLUTION If one takes the derivative of the equation, as shown, using the Quotient Rule, one finds [`\frac{dy}{dx} = \frac{-\cos (x) (x+\cos (y))+\sin (x)+y}{\sin (y) (\sin (x)+y)+x+\cos (y)}\text{.}`]
If one first clears the denominator and writes [`\sin(x)+y = \cos(y)+x`] then takes the derivative of both sides, one finds [`\frac{dy}{dx} = \frac{1-\cos(x)}{1+\sin(y)}\text{.}`]
These expressions, by themselves, are not equal. However, for values of [`x`] and [`y`] that satisfy the original equation (i.e, for [`x`] and [`y`] such that [`\frac{\sin(x)+y}{\cos(y)+x}=1`]), these expressions are equal.
END_PGML_SOLUTION
